      webfonts, so naming Newsreader/IBM Plex here would silently fall back. */
   .ttl{font-family:Georgia,'Times New Roman',serif;font-size:30px;fill:#F2EDE4}
   .act{font-family:ui-monospace,'Courier New',monospace;font-size:19px;letter-spacing:2.4px;fill:#D4A85E}
   .cap{font-family:ui-monospace,'Courier New',monospace;font-size:18px;letter-spacing:1px;fill:#8D857A}
   .mv{font-family:Georgia,'Times New Roman',serif;font-size:21px;fill:#F2EDE4}
   .qn{font-family:Georgia,'Times New Roman',serif;font-size:20px;fill:#F2EDE4}
   .quo{font-family:Georgia,'Times New Roman',serif;font-size:20px;font-style:italic;fill:#D4A85E}
   .ln{fill:none;stroke:#D4A85E;stroke-width:2.4;stroke-linecap:round}
   .thin{fill:none;stroke:#D4A85E;stroke-width:1.4;stroke-linecap:round;opacity:.7}
   .node{fill:#0A0A0A;stroke:#D4A85E;stroke-width:2}
   .dot{fill:none;stroke:#5C554A;stroke-width:1;stroke-dasharray:2 5}
   .ax{fill:none;stroke:#5C554A;stroke-width:1}
